hash.setup:
class Key:
    eqs = 0
    __slots__ = ("v",)
    def __init__(self, v):
        self.v = v
    def __eq__(self, other):
        Key.eqs += 1
        return self.v == other.v
    def __hash__(self):
        return hash(self.v)

def dedup_list(keys):
    seen = []
    for k in keys:
        if k not in seen:
            seen.append(k)
    return seen

def dedup_set(keys):
    seen = set()
    for k in keys:
        if k not in seen:
            seen.add(k)
    return seen

def compares(fn, n):
    keys = [Key(i) for i in range(n)]
    Key.eqs = 0
    fn(keys)
    return Key.eqs

